//! Aseprite JSON Array imports use tiny, original sheets generated by the tests.

use std::io::Cursor;

use ponko::assets::MemorySource;
use ponko::math::IVec2;
use ponko::prelude::*;

const LAYERS: &str = include_str!("fixtures/aseprite/layers.json");
const COMPOSITE: &str = include_str!("fixtures/aseprite/composite.json");

fn png() -> Vec<u8> {
    let mut bytes = Cursor::new(Vec::new());
    let image = image::RgbaImage::from_fn(2, 2, |x, y| image::Rgba([x as u8 * 255, y as u8 * 255, 0, 255]));
    image.write_to(&mut bytes, image::ImageFormat::Png).unwrap();
    bytes.into_inner()
}

#[test]
fn aseprite_repacks_a_composite_export_and_caches_its_atlas() {
    Game::new("aseprite", 1, 1).run_headless(0, |ctx| {
        ctx.assets.add_source(
            MemorySource::new("sprites")
                .with("art/hero.json", COMPOSITE)
                .with("art/layers.png", png()),
        );
        let atlas = ctx.gfx.try_load_aseprite("art/hero.json", false).unwrap();
        let again = ctx.gfx.load_aseprite("art/hero.json", false);
        assert_eq!(atlas.frame_count(), 2);
        assert_eq!(atlas.layers(), Vec::<String>::new());
        let first = atlas.sprite(0, None).unwrap();
        let second = atlas.sprite(1, None).unwrap();
        assert_eq!(first.texture, second.texture);
        assert_eq!(first.texture, again.sprite(0, None).unwrap().texture);
        assert_ne!(first.region, second.region);
        assert!(atlas.sprite(2, None).is_none());
    });
}

#[test]
fn aseprite_tags_use_authored_frame_lengths_and_directions_per_layer() {
    Game::new("aseprite", 1, 1).run_headless(0, |ctx| {
        ctx.assets.add_source(
            MemorySource::new("sprites")
                .with("hero.json", LAYERS)
                .with("layers.png", png()),
        );
        let atlas = ctx.gfx.load_aseprite("hero.json", true);
        assert_eq!(atlas.layers(), ["Body", "Hat"]);
        assert_eq!(atlas.frame_duration(1), Some(140));
        assert_ne!(atlas.sprite(0, Some("Body")), atlas.sprite(0, Some("Hat")));
        assert!(
            atlas.sprite(1, Some("Hat")).is_some(),
            "blank cels have a transparent atlas slot"
        );
        let bounce = atlas.animation("Bounce", Some("Hat")).unwrap();
        for (seconds, frame) in [(0.059, 0), (0.060, 1), (0.200, 2), (0.400, 1), (0.541, 0), (5.0, 0)] {
            assert_eq!(
                bounce.sprite_at(seconds),
                atlas.sprite(frame, Some("Hat")),
                "time {seconds}"
            );
        }
        let bounce_once = atlas.animation("BounceOnce", Some("Body")).unwrap();
        assert_eq!(bounce_once.sprite_at(5.0), atlas.sprite(2, Some("Body")));
        let back = atlas.animation("Back", Some("Body")).unwrap();
        assert_eq!(back.sprite_at(0.0), atlas.sprite(2, Some("Body")));
        assert_eq!(back.sprite_at(0.200), atlas.sprite(1, Some("Body")));
        let reverse_bounce = atlas.animation("ReverseBounce", Some("Body")).unwrap();
        assert_eq!(reverse_bounce.sprite_at(0.350), atlas.sprite(0, Some("Body")));
        assert_eq!(reverse_bounce.sprite_at(0.410), atlas.sprite(1, Some("Body")));
        assert_eq!(atlas.slice("Hitbox", 1).unwrap().pivot, Some(IVec2::new(0, 1)));
        assert_eq!(atlas.slice("Hitbox", 2).unwrap().bounds.size(), vec2(2., 1.));
        assert!(atlas.slice("Missing", 2).is_none());
    });
}

#[test]
fn aseprite_rejects_frames_outside_the_exported_image() {
    let invalid = COMPOSITE.replace("\"x\":1", "\"x\":8");
    Game::new("aseprite", 1, 1).run_headless(0, |ctx| {
        ctx.assets.add_source(
            MemorySource::new("sprites")
                .with("bad.json", invalid)
                .with("layers.png", png()),
        );
        let err = ctx.gfx.try_load_aseprite("bad.json", false).unwrap_err();
        assert_eq!(err.kind(), ErrorKind::Decode);
        assert_eq!(err.path(), Some("bad.json"));
    });
}

#[test]
fn aseprite_hot_reload_updates_existing_playback_and_keeps_last_good_export() {
    use std::sync::{Arc, Mutex};
    use std::time::Duration;

    let folder = std::env::temp_dir().join(format!("ponko-aseprite-{}", std::process::id()));
    std::fs::create_dir_all(&folder).unwrap();
    let json = folder.join("hero.json");
    let image = folder.join("layers.png");
    std::fs::write(&json, COMPOSITE).unwrap();
    std::fs::write(&image, png()).unwrap();
    let name = json.to_str().unwrap().to_owned();
    let state = Arc::new(Mutex::new(None::<ponko::aseprite::AsepriteAnimation>));
    let animation = state.clone();
    let asset_name = name.clone();
    Game::new("aseprite", 1, 1)
        .hot_reload(true)
        .sim_system(move |ctx: &mut Ctx| {
            let current = animation.lock().unwrap();
            let playback = current.as_ref().unwrap();
            match ctx.time.sim_tick() {
                1 => {
                    assert_eq!(playback.sprite_at(0.09), playback.sprite_at(0.0));
                    std::fs::write(&json, COMPOSITE.replace("\"duration\":100", "\"duration\":25")).unwrap();
                }
                2 => {
                    assert!(ctx.assets.reloaded_files().contains(&asset_name));
                    assert_ne!(playback.sprite_at(0.09), playback.sprite_at(0.0));
                    std::fs::write(&image, b"bad PNG").unwrap();
                }
                3 => {
                    assert!(ctx.assets.reloaded_files().is_empty());
                    assert_ne!(playback.sprite_at(0.09), playback.sprite_at(0.0));
                    let mut changed = png();
                    changed.extend_from_slice(&[0; 32]);
                    std::fs::write(&image, changed).unwrap();
                }
                4 => assert!(
                    ctx.assets.reloaded_files().contains(&asset_name),
                    "repacks on a sheet-only edit"
                ),
                _ => {}
            }
            std::thread::sleep(Duration::from_millis(275));
        })
        .run_headless(5, |ctx| {
            let atlas = ctx.gfx.load_aseprite(&name, false);
            *state.lock().unwrap() = Some(atlas.animation("Run", None).unwrap());
        });
    std::fs::remove_dir_all(folder).unwrap();
}

#[test]
fn builtin_sprite_animation_uses_aseprite_timing_and_retains_sprite_style() {
    use ponko::aseprite::AsepriteAnimation;
    use ponko::d2::Sprite;

    Game::new("aseprite", 1, 1).run_headless(0, |ctx| {
        ctx.assets.add_source(
            MemorySource::new("sprites")
                .with("hero.json", COMPOSITE)
                .with("layers.png", png()),
        );
        let atlas = ctx.gfx.load_aseprite("hero.json", false);
        let first = atlas.sprite(0, None).unwrap().with_z(5.0).with_pivot(vec2(0.25, 0.75));
        let entity = ctx.world.spawn((first, atlas.animation("Run", None).unwrap()));
        ctx.world.get_mut::<AsepriteAnimation>(entity).unwrap().time = 0.10;
        ponko::systems::animate_sprites(ctx);
        let shown = ctx.world.get::<Sprite>(entity).unwrap();
        assert_eq!(shown.region, atlas.sprite(1, None).unwrap().region);
        assert_eq!((shown.z, shown.pivot), (first.z, first.pivot));
    });
}
